    if ((c == NULL) || (body == NULL) || (reference == NULL) || (innovation == NULL) || (angle == NULL)) {
        return ADCS_E_NULL;
    }

    adcs_vec3_t b;
    adcs_status_t status = adcs_vec3_normalize(body, ADCS_EPS_NORM, &b);
    if (status != ADCS_OK) {
        innovation->x = 0.0;
        innovation->y = 0.0;
        innovation->z = 0.0;
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t ref_n;
    status = adcs_vec3_normalize(reference, ADCS_EPS_NORM, &ref_n);
    if (status != ADCS_OK) {
        innovation->x = 0.0;
        innovation->y = 0.0;
        innovation->z = 0.0;
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t mapped = adcs_mat3_mul_vec(c, &ref_n);
    adcs_vec3_t p;
    status = adcs_vec3_normalize(&mapped, ADCS_EPS_NORM, &p);
    if (status != ADCS_OK) {
        innovation->x = 0.0;
        innovation->y = 0.0;
        innovation->z = 0.0;
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    *innovation = adcs_vec3_cross(&b, &p);

    double dot = adcs_vec3_dot(&b, &p);
    double clamped_dot = ADCS_CLAMP(dot, -1.0, 1.0);
    double norm_cross = adcs_vec3_norm(innovation);

    *angle = atan2(norm_cross, clamped_dot);

    return ADCS_OK;
}

