        *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
        *angle = INFINITY;
        return ADCS_E_NULL;
    }

    if (!adcs_is_finite_vec3(body) || adcs_vec3_norm(body) <= ADCS_EPS_NORM) {
        *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t b;
    if (adcs_vec3_normalize(body, ADCS_EPS_NORM, &b) != ADCS_OK) {
        *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t mapped_ref = adcs_mat3_mul_vec(c, reference);

    if (!adcs_is_finite_vec3(&mapped_ref) || adcs_vec3_norm(&mapped_ref) <= ADCS_EPS_NORM) {
        *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t p;
    if (adcs_vec3_normalize(&mapped_ref, ADCS_EPS_NORM, &p) != ADCS_OK) {
        *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    *innovation = adcs_vec3_cross(&b, &p);

    double dot_product = adcs_vec3_dot(&b, &p);
    double clamped_dot = (dot_product < -1.0) ? -1.0 : ((dot_product > 1.0) ? 1.0 : dot_product);

    *angle = atan2(adcs_vec3_norm(innovation), clamped_dot);

    return ADCS_OK;
}

